import { offlineProof } from './proof.js';
import { ALERT_KINDS } from './alerts.js';
// Same-origin UI for the free beta. GA4 (G-P6NP48RRGC) installed per issue #53; config lives in same-origin /assets/ga.js to keep CSP free of inline scripts.
import { absoluteUrl, description, htmlEscape, jsonLdScript, openGraphTags, robotsTxt, sitemapXml, PUBLIC_ORIGIN, PUBLIC_ROUTES, PRICING_ROUTE } from './seo.js';
import { DEFAULT_PLANS, listPlans } from '../billing/index.js';
import { DEFAULT_CONTACT, TRUST_UPDATED, trustDocument } from './trust.js';
// IndexNow ownership key: public by design, served at /<key>.txt per the protocol.
const INDEXNOW_KEY = '8459b118d7f227de932db7f94357f430';
// options.publicPricing is an owner gate (COSTCAP_PUBLIC_PRICING=enabled). Off: no /pricing page, no sitemap entry.
export function uiResponse(path, siteKey = '', origin = PUBLIC_ORIGIN, billing = false, stripeMode = 'live', { publicPricing = false, plans = DEFAULT_PLANS, checkout = billing, contact = DEFAULT_CONTACT, operator } = {}) {
  const headers = { 'cache-control': 'no-store', 'x-content-type-options': 'nosniff',
    'referrer-policy': 'no-referrer', 'content-security-policy': "default-src 'self'; script-src 'self' https://challenges.cloudflare.com https://www.googletagmanager.com; frame-src https://challenges.cloudflare.com; style-src 'self'; connect-src 'self' https://challenges.cloudflare.com https://www.google-analytics.com https://region1.google-analytics.com; img-src 'self' data: https://www.google-analytics.com; base-uri 'none'; form-action 'self'; frame-ancestors 'none'" };
  if (path === '/proof/offline-policy.txt') return { body: offlineProof, headers: { ...headers, 'content-type': 'text/plain; charset=utf-8' } };
  if (path === '/') return { body: page(origin, billing, stripeMode, { publicPricing, plans, checkout }), headers: { ...headers, 'content-type': 'text/html; charset=utf-8' } };
  if (path === '/cli') return { body: cliPage(origin), headers: { ...headers, 'content-type': 'text/html; charset=utf-8' } };
  const trust = trustDocument(path, { contact, ...(operator ? { operator } : {}) });
  if (trust) return { body: trustPage(origin, trust, publicPricing), headers: { ...headers, 'content-type': 'text/html; charset=utf-8' } };
  if (path === PRICING_ROUTE.path && publicPricing) return { body: pricingPage(origin, billing, stripeMode, plans), headers: { ...headers, 'content-type': 'text/html; charset=utf-8' } };
  if (path === `/${INDEXNOW_KEY}.txt`) return { body: INDEXNOW_KEY, headers: { ...headers, 'content-type': 'text/plain; charset=utf-8' } };
  if (path === '/robots.txt') return { body: robotsTxt(origin), headers: { ...headers, 'content-type': 'text/plain; charset=utf-8' } };
  if (path === '/sitemap.xml') return { body: sitemapXml(origin, undefined, publicPricing ? [...PUBLIC_ROUTES, PRICING_ROUTE] : PUBLIC_ROUTES), headers: { ...headers, 'content-type': 'application/xml; charset=utf-8' } };
  if (path === '/assets/app.css') return { body: css, headers: { ...headers, 'content-type': 'text/css; charset=utf-8' } };
  if (path === '/assets/app.js') return { body: js, headers: { ...headers, 'content-type': 'text/javascript; charset=utf-8' } };
  if (path === '/assets/ga.js') return { body: gaJs, headers: { ...headers, 'content-type': 'text/javascript; charset=utf-8' } };
  if (path === '/ui/config') return { body: JSON.stringify({ siteKey }), headers: { ...headers, 'content-type': 'application/json' } };
  return null;
}
const page = (origin, billing, stripeMode = 'live', { publicPricing = false, plans = DEFAULT_PLANS, checkout = billing } = {}) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="${description(billing)}"><title>CostCap | Spend cap for AI agents</title><link rel="canonical" href="${origin}">${openGraphTags(origin, '/')}<link rel="stylesheet" href="/assets/app.css"><script async src="https://www.googletagmanager.com/gtag/js?id=G-P6NP48RRGC"></script><script src="/assets/ga.js" defer></script><script src="/assets/app.js" defer></script><script type="application/ld+json">${jsonLdScript(origin, billing)}</script></head>
<body><header><a class="brand" href="/">CostCap<span class="badge">FREE BETA</span></a><button id="logout" hidden>Sign out</button></header>
<main><section id="login" class="hero"><div><p class="eyebrow">KEEP YOUR AGENTS IN BUDGET</p><h1>Know the spend.<br>Control the fleet.</h1><p class="lede">Set caps, catch retry loops, and freeze enrolled agents from one place.</p><p><a href="/cli">Run the local spend cap: one wrap command, no sign-in</a>${publicPricing ? ' · <a href="/pricing">Compare plans</a>' : ''}</p><p class="boundary">Guardrails, not guarantees. Only proxy-routed traffic is controlled. Receipt-based caps can overshoot by one accepted request.</p><div class="proof"><span>CLI stays free</span><span>${billing ? "Free beta. Optional $19/month plan." : stripeMode === "test" ? "Test mode. No public price." : "No card. No charges."}</span><span>Separate org per new email</span></div><p><a href="/proof/offline-policy.txt">Read the offline policy proof and its limits</a></p></div>
<div class="card"><h2>Open your workspace</h2><p>Sign in with an email code. A new email creates a separate organization. Shared company domains do not grant access to another workspace.</p><form id="request"><label for="email">Email address</label><input id="email" type="email" autocomplete="email" required maxlength="295" placeholder="you@company.com"><div id="challenge"></div><button class="primary" id="requestButton" type="submit" disabled>Send sign-in code</button></form><form id="verify" hidden><label for="code">8-digit email code</label><input id="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" required><button class="primary" type="submit">Verify and open workspace</button><button id="restart" type="button">Use another email</button><p>Code expires in 10 minutes.</p></form><p id="loginStatus" role="status" aria-live="polite"></p></div></section>
<section id="workspace" hidden>${onboardingCard(origin)}${billing ? '<section class="card" id="plan"><h2>Hosted workspace plan</h2><p>$19 USD per month. Automatic monthly renewal. Cancel through the billing portal; cancellation stops the next renewal. The CLI stays free and existing beta access remains available.</p><p id="billingStatus" role="status">Checking subscription...</p><p id="checkoutNote"></p>' + checkoutTerms + '<button id="upgrade" type="button">Review $19/month subscription</button><button id="upgradeTeam" type="button" hidden>Review $79/month Team (Agent Guardrails bundle)</button><button id="portal" type="button" hidden>Manage or cancel subscription</button>' + planCompare(plans) + '</section>' : stripeMode === "test" && checkout ? '<section class="card" id="plan"><h2>Hosted workspace plan</h2><p>Test mode. No public price and no live charge. Checkout uses the owner test price. A canceled, unpaid, or expired test subscription returns this workspace to the free beta.</p><p id="billingStatus" role="status">Checking subscription...</p><p id="checkoutNote"></p>' + checkoutTerms + '<button id="upgrade" type="button">Continue in test mode: Solo</button><button id="upgradeTeam" type="button" hidden>Continue in test mode: Team</button><button id="portal" type="button" hidden>Manage or cancel subscription</button>' + planCompare(plans) + '</section>' : ''}<div class="heading"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>Fleet guardrails</h1><p>Policies apply to enrolled agents. Offline agents keep their last-known policy.</p></div><button id="refresh">Refresh fleet</button></div><p id="status" role="status" aria-live="polite"></p>
<div class="metrics"><div class="card"><span>Enrolled agents</span><strong id="agentCount">0</strong></div><div class="card"><span>Synced receipt cost</span><strong id="cost">$0.00</strong><small id="costPeriod">Period: every synced receipt in your plan's retention window. Reported cost, not provider-bill reconciliation.</small></div><div class="card"><span>Unknown-cost receipts</span><strong id="unknown">0</strong><small>Unknown cost is never counted as zero.</small></div></div>
<section class="card" id="spendCard"><h2>Spend</h2><p>Synced receipt cost by budget-period day (UTC unless set below), model, agent and team. Unknown cost is counted, never shown as $0; a bucket with unknown cost is marked incomplete.</p><form id="spendPeriod" class="inline"><label>Period <select name="period" id="spendPeriodSelect"><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option><option value="month">This month</option></select></label></form><p id="spendTotal" role="status"></p><div class="split"><div><h3>By day</h3><div id="spendDays"></div></div><div><h3>Top models</h3><div id="spendModels"></div><h3>Top agents</h3><div id="spendAgents"></div></div></div><h3>By team</h3><p><small>Uses current team membership.</small> <a id="spendCsv" href="/v1/spend.csv?group_by=team&amp;period=month">Download CSV</a></p><div id="spendTeams"></div><h3>By tag</h3><form id="spendTagForm" class="inline"><label>Tag key<input id="spendTagKey" name="tagKey" type="text" maxlength="32" placeholder="customer" autocomplete="off"></label><button type="submit">Show</button></form><div id="spendTags"></div></section>
<section class="card" id="unknownCard"><h2>Unknown-cost receipts</h2><p>Settle an unknown cost with an audited value from provider evidence. The original receipt stays unknown; budgets use the settled cost.</p><div id="unknownRows"></div></section>
<p><a id="receiptsCsv" href="/v1/receipts.csv">Download this workspace's receipts (CSV)</a>. The file is what the proxy reported, not a provider bill.</p><form id="receiptsExport" class="inline"><label>Since <input type="date" name="since"></label><label>Until <input type="date" name="until"></label><label>Agent <select name="agent_id" id="receiptsAgent"><option value="">All agents</option></select></label><button type="submit">Download filtered CSV</button></form><p id="receiptsNote" role="status"></p>
<div class="split"><section class="card"><h2>Enroll an agent</h2><p>Issue a one-use token, valid for 10 minutes. Treat it as a secret. Choose USD caps before enrolling.</p><form id="enroll"><div class="capfields"><label>Per run<input name="run" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Per day<input name="day" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Per week<input name="week" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Per month<input name="month" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Max steps per run<input name="maxSteps" type="number" min="1" step="1" placeholder="Optional"></label></div><button class="primary" type="submit">Create enrollment token</button></form><div id="enrollment" hidden><p>Copy this token into your local CostCap enrollment command. It is shown only in this browser session.</p><code id="token"></code><p>On the agent's machine, from a CostCap checkout:</p><code id="enrollCmd"></code><button id="copyToken">Copy token</button><button id="hideToken">Hide token</button></div><section class="card" id="alertDest"><h2>Alert destinations</h2><p>Where spend alerts for this organization go. Email recipients must be verified members. The Slack webhook is stored masked and never shown in full.</p><p>Emails: <span id="alertEmails">none</span><br>Slack: <span id="alertSlack">not set</span><br>Signed webhook: <span id="alertWebhook">not set</span></p><button type="button" id="rotateWebhook" hidden>Rotate secret</button><button type="button" id="testAlert" hidden>Send test alert</button><ul id="testAlertResults" hidden></ul><p id="webhookSecretBox" hidden>Signing secret (shown once, copy it now): <code id="webhookSecret"></code></p><form id="alertForm"><label>Member emails (comma separated)<input name="emails" type="text" autocomplete="off" maxlength="2000"></label><label>Slack webhook (leave blank to keep)<input name="slack" type="password" autocomplete="off" maxlength="300" placeholder="https://hooks.slack.com/services/..."></label><label><input name="clearSlack" type="checkbox"> Remove Slack webhook</label><label>Signed webhook URL (https, leave blank to keep)<input name="webhook" type="url" autocomplete="off" maxlength="500" placeholder="https://alerts.example.com/costcap"></label><label><input name="clearWebhook" type="checkbox"> Remove signed webhook</label><fieldset id="defaultKinds"><legend>Default kinds (email and Slack; the signed webhook gets every alert)</legend>${ALERT_KINDS.map((k) => `<label class="kindopt"><input type="checkbox" name="kind" value="${k}" checked> ${k}</label>`).join('')}</fieldset><button class="primary">Save destinations</button></form><h3>Alert routes</h3><p>Send chosen alert kinds for chosen teams to their own emails or Slack channel, in addition to the defaults. Up to 10.</p><p id="defaultKindsView"></p><ul id="alertRoutes"></ul><form id="routeForm"><input type="hidden" name="rid"><label>Route name<input name="rname" type="text" maxlength="40" required autocomplete="off"></label><label>Teams (comma separated, blank = any team)<input name="teams" type="text" autocomplete="off" maxlength="2000"></label><label>Kinds (comma separated, blank = all)<input name="kinds" type="text" autocomplete="off" maxlength="300"></label><label>Member emails (comma separated)<input name="emails" type="text" autocomplete="off" maxlength="2000"></label><label>Slack webhook (leave blank to keep)<input name="slack" type="password" autocomplete="off" maxlength="300" placeholder="https://hooks.slack.com/services/..."></label><button class="primary" type="submit">Save route</button><button type="button" id="routeReset">New route</button></form></section><form id="invite"><h2>Invite a teammate</h2><p>They join this organization when they verify that email. A shared domain is not an invitation. ${billing ? "Optional hosted plan available." : stripeMode === "test" ? "Test mode. No public price." : "Billing stays disabled."}</p><label>Email address<input name="email" type="email" autocomplete="off" required maxlength="295"></label><label>Role<select name="role"><option value="viewer">Viewer</option><option value="admin">Admin</option></select></label><button class="primary" type="submit">Send invitation</button></form><div id="invites"></div><section id="membersCard"><h2>Members</h2><div id="members"></div></section></section><section class="card"><h2>How enforcement works</h2><p>Wrap each agent with the CostCap CLI and route supported provider traffic through its local proxy. Enrollment syncs policies and receipts.</p><p>Kill and resume are remote policy changes, not a network-level kill switch. An offline agent cannot receive a new freeze until it reconnects.</p><p>${billing ? "Optional hosted plan: $19/month. No provider-bill guarantee." : stripeMode === "test" ? "Test mode. No public price. No provider-bill guarantee." : "Free beta. Billing is disabled."} The hosted datastore is single-process, not a high-availability service.</p></section></div>
<section class="card" id="fleetFreeze"><h2>Freeze all agents</h2><p>Kill switch for a runaway-spend incident. Every enrolled agent refuses new requests at its next policy poll. This is not instant, and it does not undo requests already accepted. Resume only revives agents this freeze stopped.</p><p>Fleet state: <strong id="fleetState">ACTIVE</strong></p><form id="freezeForm"><label>Reason (required, recorded in the audit log)<input id="freezeReason" name="reason" required maxlength="500" autocomplete="off"></label><button id="freezeAll" class="danger" type="submit">Freeze all agents</button><button id="resumeFleet" type="button" hidden>Resume fleet</button></form></section>
<section class="card" id="budgetPeriodCard"><h2>Budget period</h2><p>Day and month caps, alerts and the Spend card reset at midnight in this timezone, and the month starts on this day. Default: UTC, day 1. Enrolled agents pick it up on their next sync.</p><p id="budgetPeriodNow" role="status"></p><form id="budgetPeriodForm" class="inline"><label>Timezone<select name="timezone" id="budgetTimezone"></select></label><label>Month starts on day<input name="monthStartDay" id="budgetMonthStartDay" type="number" min="1" max="28" step="1" required></label><button id="budgetPeriodSave" type="submit">Save period</button></form></section><section class="card" id="digestCard"><h2>Weekly spend digest</h2><p>Spend for the previous week vs the week before, top agents, teams and models, cap headroom, unsettled unknown cost and alerts fired, sent once a week to your alert destinations. Times use your budget-period timezone.</p><form id="digestForm" class="inline"><label><input name="enabled" id="digestEnabled" type="checkbox"> Send weekly digest</label><label>Day<select name="weekday" id="digestWeekday"><option value="1">Monday</option><option value="2">Tuesday</option><option value="3">Wednesday</option><option value="4">Thursday</option><option value="5">Friday</option><option value="6">Saturday</option><option value="0">Sunday</option></select></label><label>Hour (0-23)<input name="hour" id="digestHour" type="number" min="0" max="23" step="1" required></label><label><input type="checkbox" name="ch_email" id="digestEmail"> Email</label><label><input type="checkbox" name="ch_slack" id="digestSlack"> Slack</label><label><input type="checkbox" name="ch_webhook" id="digestWebhook"> Webhook</label><button id="digestSave" type="submit">Save digest</button><button id="digestPreview" type="button">Preview</button></form><p id="digestNow" role="status"></p><pre id="digestPreviewText" hidden></pre></section><section class="card" id="retentionCard"><h2>Receipt retention</h2><p>Permanently delete synced receipts older than this many days. A nightly job runs the deletion and records it in the audit log. Receipts from the last 32 days or the current budget month, and receipts with unknown or pending cost, are always kept. Leave empty to keep everything.</p><p id="retentionNow" role="status"></p><form id="retentionForm" class="inline"><label>Keep receipts for (days)<input name="days" id="retentionDays" type="number" min="7" step="1" placeholder="Keep all"></label><button id="retentionSave" type="submit">Save retention</button></form></section><section class="card" id="tagCapsCard"><h2>Tag caps</h2><p>Fleet-wide per-tag budgets (for example one $5 UTC-day cap for every <code>customer</code>). Every enrolled agent enforces them against the org's synced spend plus its own unsynced receipts. A local <code>--tag-cap</code> can tighten a rule, never loosen it. Up to 10 rules.</p><ul id="tagCaps"></ul><form id="tagCapForm" class="inline"><label>Tag key<input name="key" type="text" required maxlength="32" pattern="[a-z0-9_.\-]{1,32}" placeholder="customer" autocomplete="off"></label><label>Window<select name="scope"><option value="day">UTC day</option><option value="week">Week (Mon)</option><option value="month">UTC month</option></select></label><label>USD<input name="usd" type="number" min="0.01" step="0.01" required></label><label>Warn at (%)<input name="warn" id="tagCapWarn" type="text" placeholder="80" title="Comma separated, e.g. 50, 80. Empty uses 80."></label><button id="tagCapAdd" type="submit">Add rule</button></form></section><section class="card" id="orgBudgetCard"><h2>Org budget</h2><p>One day, week or month cap for every agent in this workspace together, including agents enrolled later. Each enrolled agent enforces it against the org's synced spend plus its own unsynced receipts (one poll interval of overshoot). Unknown cost refuses calls until it is settled.</p><p id="orgBudgetState">No org budget.</p><form id="orgBudgetForm" class="inline"><label>Day USD<input name="day" id="orgBudgetDay" type="number" min="0.01" step="0.01" placeholder="none"></label><label>Week USD<input name="week" id="orgBudgetWeek" type="number" min="0.01" step="0.01" placeholder="none"></label><label>Month USD<input name="month" id="orgBudgetMonth" type="number" min="0.01" step="0.01" placeholder="none"></label><button id="orgBudgetSave" type="submit">Save org budget</button></form></section>
<section class="card" id="apiKeysCard"><h2>API keys</h2><p>Revocable keys for scripts, CI and incident tooling. A viewer key reads spend, exports and alerts. An admin key can also freeze the fleet, change policy, settle receipts and acknowledge alerts. Keys can't manage keys, billing or members. The full key is shown once.</p><ul id="apiKeys"></ul><p id="apiKeyNew" hidden>New key (copy it now, it won't be shown again): <code id="apiKeyValue"></code></p><form id="apiKeyForm"><label>Key name<input name="name" type="text" required maxlength="100"></label><label>Role<select name="role"><option value="viewer">viewer</option><option value="admin">admin</option></select></label><button class="primary" id="apiKeyCreate">Create key</button></form></section><section class="card" id="teamsCard"><h2>Team budgets</h2><p>A team shares one day and month cap across its agents. Agent caps apply first. Team spend counts synced receipts only, so spend not yet synced can overshoot until the next poll.</p><div id="teams"></div><form id="teamForm"><label>Team name<input name="name" type="text" required maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9_-]*"></label><fieldset id="teamAgents"><legend>Agents</legend></fieldset><div class="capfields"><label>Per day<input name="day" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Per week<input name="week" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Per month<input name="month" type="number" min="0" step="0.01" placeholder="Optional"></label><label>Warn at (%)<input name="warnAt" type="text" placeholder="80 (default)" title="Comma separated, e.g. 50, 80, 95. off turns warnings off."></label></div><button class="primary">Save team</button></form></section><section class="card"><h2>Agents and caps</h2><div id="agents"></div><p id="empty">No enrolled agents yet. Create a token above to start.</p></section>
<section class="card" id="capRequestsCard"><h2>Cap raise requests</h2><p>Agents and members can ask for a time-boxed raise. Approving adds budget until it expires; base caps never change.</p><div id="capRequests"></div></section><div class="split"><section class="card"><h2>Alerts</h2><div id="alerts"></div></section><section class="card"><h2>Audit log</h2><p><a id="auditCsv" href="/v1/audit.csv">Download audit log (CSV)</a></p><div id="audit"></div></section></div></section></main>${siteFooter(publicPricing)}</body></html>`;
// FA-CC-02: legal links on every public page and next to checkout.
const LEGAL_LINKS = [['/privacy', 'Privacy'], ['/terms', 'Terms'], ['/security', 'Security']];
const siteFooter = (pricing = false, extra = '') => `<footer>CostCap · Guardrails, not guarantees · Free beta${extra ? ` · ${extra}` : ''}<nav class="legal" aria-label="Legal">${(pricing ? [['/pricing', 'Pricing'], ...LEGAL_LINKS] : LEGAL_LINKS).map(([href, label]) => `<a href="${href}">${label}</a>`).join(' · ')}</nav></footer>`;
const checkoutTerms = '<p class="terms" id="checkoutTerms">By continuing to checkout you accept the <a href="/terms">Terms</a>. See <a href="/privacy">Privacy</a> for what Stripe and CostCap store.</p>';
// Static trust page (privacy, terms, security). Content comes from trust.js; every string is escaped.
const trustPage = (origin, doc, pricing) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="${htmlEscape(doc.description)}"><title>${htmlEscape(doc.title)}</title><link rel="canonical" href="${absoluteUrl(origin, doc.path)}">${openGraphTags(origin, doc.path, doc.title, doc.description)}<link rel="stylesheet" href="/assets/app.css"><script async src="https://www.googletagmanager.com/gtag/js?id=G-P6NP48RRGC"></script><script src="/assets/ga.js" defer></script></head>
<body><header><a class="brand" href="/">CostCap<span class="badge">FREE BETA</span></a><a href="/">Hosted workspace</a></header>
<main class="doc" data-trust="${htmlEscape(doc.path.slice(1))}"><p class="eyebrow">TRUST</p><h1>${htmlEscape(doc.heading)}</h1><p class="lede">${htmlEscape(doc.lede)}</p>${doc.sections.map((s) => `<section class="card"><h2>${htmlEscape(s.heading)}</h2><ul>${s.items.map((i) => `<li>${linkify(i)}</li>`).join('')}</ul></section>`).join('')}<p><small>Last updated ${htmlEscape(TRUST_UPDATED)}.</small></p></main>${siteFooter(pricing)}</body></html>`;
// Escape first, then turn bare https URLs into links. Only https URLs become links.
const linkify = (text) => htmlEscape(text).replace(/https:\/\/[A-Za-z0-9./_?=&;#%-]+[A-Za-z0-9/]/g, (url) => `<a href="${url}" rel="noopener">${url}</a>`);
// First-run checklist (hidden until /v1/fleet says onboarding is incomplete).
const onboardingCard = (origin) => `<section class="card" id="onboarding" hidden><p class="eyebrow">GET STARTED</p><h2>See your first agent's spend</h2><ol id="onboardingSteps"><li data-step="token">Set caps and create an enrollment token in <a href="#enroll">Enroll an agent</a>.</li><li data-step="enroll">On the agent's machine, enroll it with the token:<code>COSTCAP_ENROLL_TOKEN=&lt;token&gt; node src/cli.js enroll --url ${htmlEscape(origin)} --name my-agent</code></li><li data-step="receipt">Run the agent wrapped. Its first receipt shows here with estimated spend:<code>node src/cli.js wrap --enrollment .costcap/enrollment.json -- node your-agent.js</code></li></ol><p id="onboardingStatus" role="status"></p></section>`;
// Free vs paid comparison inside the plan card. Limits come from the plan catalog.
const planCompare = (plans) => `<div class="plans">${listPlans(plans).filter((p) => p.hosted).map((p) => `<div class="tier" data-plan="${htmlEscape(p.id)}"><h3>${htmlEscape(p.name)}</h3><ul>${p.features.map((f) => `<li>${htmlEscape(f)}</li>`).join('')}</ul></div>`).join('')}</div><p id="planUsage" role="status"></p>`;
const lede = (plans) => {
  const free = listPlans(plans).find((p) => p.hosted && !p.paid);
  const limits = free?.limits ?? {};
  return `The CLI is free. The hosted workspace is free for up to ${limits.agents ?? 'a few'} agents and ${limits.seats ?? 'a few'} people. Paid plans raise those limits.`;
};
// Public pricing page (FA-CC-03). On by default; COSTCAP_PUBLIC_PRICING=disabled turns it off.
// Paid tiers show the catalog list price. Test mode shows a banner: checkout is Stripe test mode, no real charge.
const pricingBanner = (billing, stripeMode) => stripeMode === 'test'
  ? '<p class="banner" id="testModeBanner" role="note"><strong>Test mode.</strong> Checkout runs in Stripe test mode with the owner test prices. No real charge is made, and a test subscription can be canceled in the billing portal.</p>'
  : billing ? '' : '<p class="banner" role="note"><strong>Not on sale yet.</strong> The hosted workspace is a free beta today.</p>';
const onSale = (p, stripeMode) => !p.testModeOnly || stripeMode === 'test';
const tierPrice = (p, stripeMode) => !p.paid ? 'Free' : !onSale(p, stripeMode) ? `Not on sale yet ($${p.priceUsdMonthly} USD per month planned)` : Number.isFinite(p.priceUsdMonthly) ? `$${p.priceUsdMonthly} USD per month` : 'Paid plan';
const tierCta = (p, stripeMode) => !onSale(p, stripeMode) ? '<span class="muted">Not on sale yet</span>' : !p.hosted ? '<a class="cta" href="/cli">Run the CLI</a>' : p.paid ? `<a class="cta" href="/?plan=${encodeURIComponent(p.id)}#plan">Choose ${htmlEscape(p.name)} in your workspace</a>` : '<a class="cta" href="/#login">Open a free workspace</a>';
// Meta and OG copy from the same catalog Checkout reads back, so the prices cannot drift.
export const pricingMeta = (plans = DEFAULT_PLANS) => {
  const paid = listPlans(plans).filter((p) => p.hosted && p.paid && Number.isFinite(p.priceUsdMonthly));
  const label = (p) => `${p.name}${p.bundle ? ` (${p.bundle} bundle)` : ''}`;
  return {
    description: `CostCap plans: free CLI, a free hosted workspace${paid.map((p) => `, ${label(p)} at $${p.priceUsdMonthly} per month`).join('')}. Guardrails, not a provider-bill guarantee.`,
    og: `Free CLI, a free hosted workspace${paid.map((p) => `, ${p.name} $${p.priceUsdMonthly}`).join('')} per month. Guardrails, not guarantees.`,
  };
};
