// Public, indexable CLI page (issue #90). Static: no scripts beyond GA, no sign-in.
const cliPage = (origin) => `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Wrap an AI agent with CostCap's local proxy to stop further API calls once a USD spend cap is reached. Install from source. Limits stated up front."><title>CostCap CLI | Local spend cap for AI agent API calls</title><link rel="canonical" href="${absoluteUrl(origin, '/cli')}">${openGraphTags(origin, '/cli', 'CostCap CLI: a local spend cap for AI agent API calls', 'One wrap command puts a local hard stop on proxy-routed AI agent API spend. Prices are estimates. Guardrails, not guarantees.')}<link rel="stylesheet" href="/assets/app.css"><script async src="https://www.googletagmanager.com/gtag/js?id=G-P6NP48RRGC"></script><script src="/assets/ga.js" defer></script></head>
<body><header><a class="brand" href="/">CostCap<span class="badge">FREE BETA</span></a><a href="/">Hosted workspace</a></header>
<main class="doc"><p class="eyebrow">LOCAL SPEND CAP FOR AI AGENTS</p><h1>Stop an agent's API spend at a cap you set.</h1><p class="lede">CostCap wraps your agent process with a local metering proxy. Once the cap is reached, further provider calls are refused. No account or sign-in needed.</p>
<section class="card"><h2>Install from source</h2><p>The npm package is not published yet. Node 20 or newer. The CLI needs no npm install; the optional pg driver is used only by the hosted service.</p><pre><code>git clone https://github.com/persooninc/costcap.git
cd costcap</code></pre></section>
<section class="card"><h2>Wrap your agent</h2><pre><code>node src/cli.js wrap --cap 5 --day-cap 10 --max-steps 40 -- node your-agent.js</code></pre><p><code>--cap</code> is USD per run, <code>--day-cap</code> and <code>--month-cap</code> are USD per UTC day and month, and <code>--max-steps</code> limits provider calls. Pause every agent sharing the kill file with <code>node src/cli.js kill "reason"</code>, then <code>node src/cli.js resume</code>.</p></section>
<section class="card"><h2>Enforcement limits</h2><ul>
<li><strong>Only proxy-routed calls are capped.</strong> The wrapper sets provider base URL environment variables. SDKs that ignore them, hardcoded endpoints, and subprocesses that drop them bypass CostCap.</li>
<li><strong>One accepted call can exceed the remaining cap.</strong> Cost is metered from provider-reported usage after each response, so the call that crosses the cap completes. Calls after it are refused. This is not a prepaid reservation.</li>
<li><strong>Prices are estimates.</strong> Cost comes from a versioned price table, not your provider invoice. Unknown models use a declared fallback rate. Check <code>src/pricing-table.json</code> before relying on rates.</li>
<li>Missing usage or an uncertain network outcome pauses further calls. Unknown cost is never counted as zero.</li>
<li>Day and month caps use UTC. Separate receipt ledgers do not share day or month caps.</li>
<li>The kill file does not undo a request the provider already accepted, and it does not stop remote agents.</li>
<li>The proxy binds to 127.0.0.1 for a trusted local machine. It is not an authentication boundary against other local processes.</li>
</ul></section>
<p><a href="https://github.com/persooninc/costcap#enforcement-limits">Full enforcement limits in the README</a> · <a href="/proof/offline-policy.txt">Offline policy proof and its limits</a></p></main>${siteFooter(false, 'MIT, no warranty')}</body></html>`;
